        public override object InvokeData(System.Collections.Hashtable p)
        {
            // Get credit information
            CreditBalanceBO boCreditBalance = new CreditBalanceBO(CurrentUserSession.NetSessionId);
            Hashtable creditBalance = boCreditBalance.GetCreditBalance();

            // Get PT message status
            UserMessageBO boUserMessage = new UserMessageBO(CurrentUserSession.NetSessionId);
            DataTable dt = boUserMessage.GetPopupMessageStatus();

            bool isPTChanged = false, isBettingLimitChanged = false;
            if (dt != null)
            {
                foreach (DataRow row in dt.Rows)
                {
                    if (!dt.Columns.Contains("typeid"))
                    {
                        break;
                    }

                    int typeId = 0;

                    int.TryParse(row["typeid"] + string.Empty, out typeId);

                    if (typeId == 1) // For PT Change
                    {
                        isPTChanged = true;
                    }
                    else if (typeId == 2) // For Betting Limit Change
                    {
                        isBettingLimitChanged = true;
                    }
                }
            }

            if (isPTChanged || isBettingLimitChanged)
            {
                boUserMessage.UpdateViewedPTMessage(true);
            }

            return new object[] { creditBalance, isPTChanged, isBettingLimitChanged };
        }
